exercise.solution:
def unusual(value,mean,sd,limit=3):
    if sd<=0: raise ValueError("positive spread required")
    return abs(value-mean)/sd > limit

exercise.tests:
assert unusual(10,2,1)
assert not unusual(3,2,1)
try: unusual(2,2,0)
except ValueError: pass
else: raise AssertionError("undefined z score")

